/* {v}：0 → v；{v:b}：b → v。品質說明的數字照目前品質換算 */
const qualText = (k, q) =>
  (QUAL[k] || '').replace(/\{([\d.]+)(?::([\d.]+))?\}/g, (_, v, b) => {
    const b0 = b ? +b : 0;
    return String(+(b0 + ((+v - b0) * q) / GEM_Q_MAX).toFixed(2));
  });
/* 一次提升幾 %：技能、光環 1%，輔助 2%；每次 1 精粉 */
